module rain_optimizer (\n    input clk,\n    input rst_n,\n    input start,\n    input [7:0] d,\n    input [7:0] t,\n    input [7:0] c,\n    input [7:0] r,\n    input [7:0] cloud_start [0:7],\n    input [7:0] cloud_end [0:7],\n    input [15:0] cloud_prob [0:7],\n    input [7:0] cloud_intensity [0:7],\n    input [7:0] roof_start [0:3],\n    input [7:0] roof_end [0:3],\n    output reg [31:0] result,\n    output reg done\n);\n\nlocalparam [2:0] IDLE       = 3'd0;\nlocalparam [2:0] COMPUTE_E  = 3'd1;\nlocalparam [2:0] DP_INIT    = 3'd2;\nlocalparam [2:0] DP_COMPUTE = 3'd3;\nlocalparam [2:0] FINISHED   = 3'd4;\n\nreg [2:0] state, next_state;\nreg [7:0] time_idx, pos_idx;\nreg [7:0] cloud_idx;\nreg [31:0] dp_next [0:15];\nreg [31:0] dp_curr [0:15];\nreg [31:0] E [0:15];\nreg [3:0] roof_mask [0:15];\n\nfunction [31:0] min;\n    input [31:0] a, b;\n    begin\n        min = (a < b) ? a : b;\n    end\nendfunction\n\nalways @(*) begin\n    for (integer i = 0; i < 16; i = i + 1) begin\n        roof_mask[i] = 1'b0;\n    end\n    for (integer j = 0; j < 4; j = j + 1) begin\n        if (j < r) begin\n            for (integer k = 0; k < 16; k = k + 1) begin\n                if (k >= roof_start[j] && k < roof_end[j]) begin\n                    roof_mask[k] = 1'b1;\n                end\n            end\n        end\n    end\nend\n\nalways @(posedge clk or negedge rst_n) begin\n    if (!rst_n) begin\n        state <= IDLE;\n    end else begin\n        state <= next_state;\n    end\nend\n\nalways @(*) begin\n    next_state = state;\n    case (state)\n        IDLE:       if (start) next_state = COMPUTE_E;\n        COMPUTE_E:  if (cloud_idx >= c) next_state = DP_INIT;\n        DP_INIT:    next_state = DP_COMPUTE;\n        DP_COMPUTE: if (time_idx == 8'd0 && pos_idx == 8'd0) next_state = FINISHED;\n        FINISHED:   next_state = IDLE;\n        default:    next_state = IDLE;\n    endcase;\nend\n\nalways @(posedge clk or negedge rst_n) begin\n    integer i;\n    if (!rst_n) begin\n        done <= 1'b0;\n        result <= 32'd0;\n        cloud_idx <= 8'd0;\n        time_idx <= 8'd0;\n        pos_idx <= 8'd0;\n        for (i = 0; i < 16; i = i + 1) begin\n            E[i] <= 32'd0;\n            dp_next[i] <= 32'h7FFFFFFF;\n            dp_curr[i] <= 32'h7FFFFFFF;\n        end\n    end else begin\n        case (state)\n            IDLE: begin\n                done <= 1'b0;\n                cloud_idx <= 8'd0;\n                time_idx <= 8'd0;\n                pos_idx <= 8'd0;\n            end\n            \n            COMPUTE_E: begin\n                if (cloud_idx < c) begin\n                    for (integer tm = 0; tm < 16; tm = tm + 1) begin\n                        if (tm >= cloud_start[cloud_idx] && tm < cloud_end[cloud_idx]) begin\n                            E[tm] <= E[tm] + ({{16{cloud_prob[cloud_idx][15]}}, cloud_prob[cloud_idx]} * cloud_intensity[cloud_idx]);\n                        end\n                    end\n                    cloud_idx <= cloud_idx + 8'd1;\n                end\n            end\n            \n            DP_INIT: begin\n                for (i = 0; i < 16; i = i + 1) begin\n                    if (i <= d) begin\n                        dp_next[i] <= 32'd0;\n                    end else begin\n                        dp_next[i] <= 32'h7FFFFFFF;\n                    end\n                end\n                time_idx <= (t > 0) ? t - 8'd1 : 8'd0;\n                pos_idx <= (d > 0) ? d - 8'd1 : 8'd0;\n            end\n            \n            DP_COMPUTE: begin\n                if (time_idx != 8'd0) begin\n                    if (roof_mask[pos_idx] && pos_idx <= d) begin\n                        dp_curr[pos_idx] <= min(dp_curr[pos_idx], dp_next[pos_idx]);\n                    end\n                    \n                    if (pos_idx < d) begin\n                        if (!roof_mask[pos_idx]) begin\n                            dp_curr[pos_idx] <= min(dp_curr[pos_idx], dp_next[pos_idx+8'd1] + E[time_idx]);\n                        end else begin\n                            dp_curr[pos_idx] <= min(dp_curr[pos_idx], dp_next[pos_idx+8'd1]);\n                        end\n                    end\n                    \n                    if (pos_idx == 8'd0) begin\n                        for (i = 0; i < 16; i = i + 1) begin\n                            dp_next[i] <= dp_curr[i];\n                            dp_curr[i] <= 32'h7FFFFFFF;\n                        end\n                        time_idx <= time_idx - 8'd1;\n                        pos_idx <= (d > 0) ? d - 8'd1 : 8'd0;\n                    end else begin\n                        pos_idx <= pos_idx - 8'd1;\n                    end\n                end\n            end\n            \n            FINISHED: begin\n                result <= dp_next[0];\n                done <= 1'b1;\n            end\n        endcase\n    end\nend\n\nendmodule